	Hub.Net = {}
	do
		local num, num2, num3 = 20, 100, 50
		local num4 = 8
		local tokens, now = 1, os.clock()
		local num5, num6 = 1, 0
		local function getNetRate()
			local num4 = tonumber(config.NetRate) or num3
			if num4 ~= num4 then
				num4 = num3
			end
			if Hub.AntiBan and Hub.AntiBan.Config and Hub.AntiBan.Config.Enabled then
				num4 = math.min(num4, Hub.AntiBan.Config.BaseRate + 5)
			end
			return math.clamp(num4, num, num2)
		end
		function Hub.Net.GetRate()
			local result = getNetRate()
			if Hub.Warmup then
				result = result * Hub.Warmup.Factor()
			end
			if Hub.Density then
				result = result * Hub.Density.Factor()
			end
			return math.max(1, math.floor(result))
		end
		local function updateTokens()
			local now2 = os.clock()
			if now2 >= num6 then
				num5 = 0.8 + math.random() * 0.4
				num6 = now2 + 0.2 + math.random() * 0.3
			end
			local factor = (Hub.Warmup and Hub.Warmup.Factor()) or 1
			tokens = math.min(num4, tokens + (now2 - now) * getNetRate() * num5 * factor)
			now = now2
		end
		function Hub.Net.TryTake()
			updateTokens()
			if tokens >= 1 then
				tokens = tokens - 1
				return true
			end
			return false
		end
		function Hub.Net.Acquire()
			local now = os.clock()
			while not Hub.Net.TryTake() do
				if not isReplayToken() or os.clock() - now > 5 then
					break
				end
				task.wait(0.008 + math.random() * 0.02)
			end
		end
		function Hub.Net.Fire(obj, ...)
			Hub.Net.Acquire()
			if Hub.AntiBan and Hub.AntiBan.IsBlocked() then
				return
			end
			if Hub.AntiBan then
				task.wait(0.02 + math.random() * 0.04)
			end
			return obj:FireServer(...)
		end
		function Hub.Net.Invoke(obj, ...)
			Hub.Net.Acquire()
			if Hub.AntiBan and Hub.AntiBan.IsBlocked() then
				return
			end
			if Hub.AntiBan then
				task.wait(0.04 + math.random() * 0.06)
			end
			return obj:InvokeServer(...)
		end
	end
	Hub.Coord = { jobs = {}, last = nil }
	function Hub.Coord.Register(arg1, arg2, arg3, arg4, arg5)
		Hub.Coord.jobs[arg1] =
			{ prio = arg2, pending = arg3, busy = arg4, giveUp = arg5 or 240, since = nil, seen = nil, warned = false }
	end
	function Hub.Coord.Blocker(value)
		local now = os.clock()
		local last = nil
		for key, value2 in pairs(Hub.Coord.jobs) do
			local ok, result = pcall(value2.busy)
			local ok2, result2 = pcall(value2.pending)
			result = ok and result == true
			result2 = ok2 and result2 == true
			if result or result2 then
				value2.since = value2.since or now
				if value2.seen and now - value2.seen > 5 then
					value2.since = now
				end
				value2.seen = now
				if (not result) and now - value2.since > value2.giveUp then
					if not value2.warned then
						value2.warned = true
						Hub.say(key .. " is taking too long - continuing with the other features")
					end
				elseif value2.prio < value and not last then
					last = key
				end
			else
				value2.since, value2.seen, value2.warned = nil, nil, false
			end
		end
		Hub.Coord.last = last
		return last
	end
	Hub.Warn = { MAX = 5, LIFETIME = 3600, list = {} }
	do
