			end)
		end
		local function handleNumber()
			local timestamp, map = os.time(), {}
			for index, item in ipairs(warn.list) do
				if type(item) == "number" and timestamp - item < warn.LIFETIME and item <= timestamp + 60 then
					map[#map + 1] = item
				end
			end
			local flag = #map ~= #warn.list
