	do
		local warn = Hub.Warn
		warn.LogOn = true
		warn.LogLines = {}
		local path = "SmoothHub/SignalLog.txt"
		local map, count = {}, 0
		function warn.Log(text, obj)
			if not warn.LogOn or count >= 600 then
				return
			end
			obj = tostring(obj):gsub("[\r\n]+", " ")
			if #obj > 160 then
				obj = obj:sub(1, 160)
			end
			local result = text .. "|" .. (obj:gsub("%d+", "#"))
			if map[result] then
				return
			end
			map[result] = true
			count += 1
			local formatted = ("][%s] %s: %s"):format(os.date("%H:%M:%S"), text, obj)
			warn.LogLines[#warn.LogLines + 1] = formatted
			pcall(function()
				if type(makefolder) == "function" and type(isfolder) == "function" and not isfolder("SmoothHub") then
					makefolder("SmoothHub")
				end
				if type(appendfile) == "function" then
					appendfile(path, formatted .. "\n")
				elseif type(writefile) == "function" then
					writefile(path, table.concat(warn.LogLines, "\n"))
				end
			end)
		end
		function warn.LogText()
			return table.concat(warn.LogLines, "\n")
		end
		task.spawn(function()
			pcall(function()
				for key, value in pairs(localPlayer:GetAttributes()) do
					if not tostring(key):match("^SH_") then
						warn.Log("ATTR", key .. " = " .. tostring(value))
					end
				end
				local map = {}
				local function handleSh(arg1)
					local text = tostring(arg1)
					if text:match("^SH_") then
						return
					end
					local attribute = localPlayer:GetAttribute(arg1)
					warn.Log("ATTR", text .. " = " .. tostring(attribute))
					local lowered = text:lower()
					if lowered:find("warn", 1, true) or lowered:find("strike", 1, true) then
						if type(attribute) == "number" then
							warn.AttrCount = math.clamp(math.floor(attribute), 0, warn.MAX)
							local element = map[arg1] or 0
							map[arg1] = attribute
							for i = 1, math.min(math.floor(attribute) - math.floor(element), warn.MAX) do
								warn.Add("attribute: " .. text .. " = " .. tostring(attribute))
							end
						end
					end
					if
						lowered:find("ban", 1, true)
						or lowered:find("exploit", 1, true)
						or lowered:find("cheat", 1, true)
						or lowered:find("blacklist", 1, true)
						or lowered:find("suspic", 1, true)
						or lowered:find("punish", 1, true)
					then
						if
							attribute == true
							or (type(attribute) == "number" and attribute ~= 0)
							or (type(attribute) == "string" and attribute ~= "" and attribute:lower() ~= "false")
						then
							warn.AttrCount = warn.MAX
						end
					end
				end
				for key in pairs(localPlayer:GetAttributes()) do
