		end
		local function handleGuiObject(arg1)
			local arg1Ref = arg1
			while arg1Ref and arg1Ref ~= game do
				if arg1Ref:IsA("GuiObject") and not arg1Ref.Visible then
					return false
				end
				if arg1Ref:IsA("ScreenGui") then
					return arg1Ref.Enabled
				end
				arg1Ref = arg1Ref.Parent
			end
			return true
