		function warn.Snapshot()
			local map, count = {}, 0
			local function recordAttr(arg1, arg2)
				map[arg1] = tostring(arg2)
			end
			pcall(function()
				for key, value in pairs(localPlayer:GetAttributes()) do
					if not tostring(key):match("^SH_") then
						recordAttr("ATTR player." .. key, value)
					end
				end
			end)
			pcall(function()
				local character = localPlayer.Character
				if character then
					for key, value in pairs(character:GetAttributes()) do
						recordAttr("ATTR character." .. key, value)
					end
					local humanoid = character:FindFirstChildOfClass("Humanoid")
					if humanoid then
						for key, value in pairs(humanoid:GetAttributes()) do
							recordAttr("ATTR humanoid." .. key, value)
						end
					end
				end
			end)
			pcall(function()
				for key, value in pairs(workspace:GetAttributes()) do
					recordAttr("ATTR workspace." .. key, value)
				end
			end)
			pcall(function()
				for index, item in ipairs(localPlayer:GetDescendants()) do
					if item:IsA("ValueBase") and not item:GetFullName():find("PlayerGui", 1, true) then
						recordAttr("VALUE " .. item:GetFullName():gsub("^Players%.[^%.]+%.", ""), item.Value)
					end
				end
			end)
			local playerGui = localPlayer:FindFirstChild("PlayerGui")
			if playerGui then
				for index, item in ipairs(playerGui:GetChildren()) do
					if item:IsA("ScreenGui") and not handleScreenGui(item) then
						recordAttr("GUI " .. item.Name, item.Enabled and "on" or "off")
					end
				end
				for index, item in ipairs(playerGui:GetDescendants()) do
					count += 1
					if count % 400 == 0 then
						task.wait()
					end
					if
						(item:IsA("TextLabel") or item:IsA("TextButton"))
						and item.Text ~= ""
						and #item.Text < 200
						and not handleScreenGui(item)
						and handleGuiObject(item)
					then
						recordAttr("TEXT " .. item:GetFullName():gsub("^Players%.[^%.]+%.PlayerGui%.", ""), item.Text)
					end
				end
			end
			return map
		end
		local function maskDigits(arg1)
			return (tostring(arg1):gsub("%d+", "#"))
		end
		function warn.Diff(data, data2)
			local map, count = {}, 0
			for key, value in pairs(data2) do
				if data[key] == nil then
					map[#map + 1] = "NEW      " .. key .. "  =  " .. value
				elseif data[key] ~= value then
					if maskDigits(data[key]) ~= maskDigits(value) then
						map[#map + 1] = "CHANGED  " .. key .. "  :  " .. data[key] .. "  ->  " .. value
					else
						count += 1
					end
				end
			end
			for key, value in pairs(data) do
				if data2[key] == nil then
					map[#map + 1] = "GONE     " .. key .. "  (was: " .. value .. ")"
				end
			end
			table.sort(map)
			local list = {
				"Smooth Hub signal compare  " .. os.date("%H:%M:%S"),
				("%d changes, %d number-only changes hidden"):format(#map, count),
				"",
			}
			for i = 1, math.min(#map, 300) do
				list[#list + 1] = map[i]
			end
			if #map > 300 then
				list[#list + 1] = ("... %d more not shown"):format(#map - 300)
			end
			return table.concat(list, "\n")
		end
		function warn.TakeBase()
			task.spawn(function()
				warn.Base = warn.Snapshot()
