	Hub.AntiBan = nil
	Hub.Stealth = {}
	do
		local stealth = Hub.Stealth
		local _ = game:GetService("UserInputService")
		stealth.Config = {
			Enabled = true,
			MouseHumanize = true,
			ErrorBackoff = true,
			ProximityCheck = true,
			PatternBreak = true,
			AdaptiveCooldown = true,
			SuspiciousPlayerScan = true,
			WatchRadius = 120,
			MaxErrorStreak = 4,
			CooldownBase = 3,
			CooldownMax = 30,
			AnomalyThreshold = 0.001,
		}
		stealth.Errors, stealth.Cooldowns, stealth.Watchers, stealth.ActionVariety = {}, {}, {}, {}
		stealth.SuspiciousScore, stealth.LastWatchScan, stealth.Clicks, stealth.LastActionAt = 0, 0, {}, 0
		function stealth.NoteError(arg1)
			if not stealth.Config.ErrorBackoff then
				return
			end
			stealth.Errors[arg1] = (stealth.Errors[arg1] or 0) + 1
			if stealth.Errors[arg1] >= stealth.Config.MaxErrorStreak then
				local num = math.min(stealth.Config.CooldownMax, stealth.Config.CooldownBase * stealth.Errors[arg1])
				stealth.Cooldowns[arg1] = os.clock() + num
				stealth.Errors[arg1] = 0
				if Hub.say then
					Hub.say("][Stealth] backoff " .. tostring(arg1) .. " " .. num .. "s")
				end
			end
		end
		function stealth.IsCooling(arg1)
			return (stealth.Cooldowns[arg1] or 0) > os.clock()
		end
		function stealth.NoteAction(arg1)
			stealth.ActionVariety[arg1] = (stealth.ActionVariety[arg1] or 0) + 1
			stealth.LastActionAt = os.clock()
		end
		function stealth.ShouldBreakPattern()
			if not stealth.Config.PatternBreak then
				return false
			end
			local count = 0
			for key, value in pairs(stealth.ActionVariety) do
				count = count + value
			end
			if count < 20 then
				return false
			end
			return math.random() < 0.05
		end
		function stealth.ScanWatchers()
			if not stealth.Config.ProximityCheck then
				return
			end
			local now = os.clock()
			if now - stealth.LastWatchScan < 2 then
				return
			end
			stealth.LastWatchScan = now
			local character = localPlayer.Character
			local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
			if not humanoidRootPart then
				return
			end
			stealth.Watchers = {}
			for index, item in ipairs(Players:GetPlayers()) do
				if item ~= localPlayer and item.Character then
					local humanoidRootPart2 = item.Character:FindFirstChild("HumanoidRootPart")
					if humanoidRootPart2 then
						local magnitude = (humanoidRootPart2.Position - humanoidRootPart.Position).Magnitude
						if magnitude <= stealth.Config.WatchRadius then
							stealth.Watchers[#stealth.Watchers + 1] = { player = item, dist = magnitude }
						end
					end
				end
			end
			table.sort(stealth.Watchers, function(data, data2)
				return data.dist < data2.dist
			end)
		end
		function stealth.IsWatched()
			return #stealth.Watchers > 0
		end
		function stealth.SuspiciousPlayer(obj)
			if not obj then
				return false
			end
			local ok, result = pcall(function()
				return obj:GetAttributes()
			end)
			if ok and type(result) == "table" then
				for key, value in pairs(result) do
					local lowered = tostring(key):lower()
					if
						lowered:find("admin")
						or lowered:find("mod")
						or lowered:find("staff")
						or lowered:find("watcher")
						or lowered:find("owner")
						or lowered:find("dev")
					then
						if value == true or (type(value) == "number" and value > 0) then
							return true
						end
					end
				end
			end
			local ok2, result2 = pcall(function()
				return obj:GetRankInGroup(game.CreatorId)
			end)
			if ok2 and result2 and result2 >= 200 then
				return true
			end
			local ok3, result3 = pcall(function()
				return obj.Name:lower()
			end)
			if ok3 and result3 and (result3:find("admin") or result3:find("moderator")) then
				return true
			end
			return false
		end
		function stealth.ScanForSuspicious()
			if not stealth.Config.SuspiciousPlayerScan then
				return false
			end
			for index, item in ipairs(Players:GetPlayers()) do
				if stealth.SuspiciousPlayer(item) then
					stealth.SuspiciousScore = math.min(20, stealth.SuspiciousScore + 1)
					if Hub.AntiBan then
						Hub.AntiBan.AddScore(8, "suspicious-player")
					end
					return true
				end
			end
			return false
		end
		function stealth.AdaptiveWait(value)
			if not stealth.Config.AdaptiveCooldown then
				return value
			end
			local count = 1
			if Hub.AntiBan then
				count = count + (Hub.AntiBan.Score or 0) / 100
			end
			if stealth.IsWatched() then
				count = count * 1.4
			end
			return value * count
		end
		function stealth.AnomalyCheck()
			if #stealth.Clicks < 5 then
				return false
			end
			local map = {}
			for i = 2, #stealth.Clicks do
				map[#map + 1] = stealth.Clicks[i] - stealth.Clicks[i - 1]
			end
			if #map < 3 then
				return false
			end
			local count, count2 = 0, 0
			for index, item in ipairs(map) do
				count = count + item
				count2 = count2 + item * item
			end
			local num = count / #map
