	Hub.NetGuard = {}
	do
		local netGuard = Hub.NetGuard
		local Stats = game:GetService("Stats")
		netGuard.Config =
			{ Enabled = true, PingThreshold = 250, LagSpikeLimit = 8, MaxFails = 5, BackoffMin = 5, BackoffMax = 60 }
		netGuard.PingHistory, netGuard.LagSpikes, netGuard.LastLagAt, netGuard.ConsecutiveFails, netGuard.BackoffUntil =
			{}, 0, 0, 0, 0
		function netGuard.MeasurePing()
			local ok, result = pcall(function()
				return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
			end)
			return (ok and tonumber(result)) or 0
		end
		function netGuard.CheckPing()
			local measurePing = netGuard.MeasurePing()
			netGuard.PingHistory[#netGuard.PingHistory + 1] = measurePing
			if #netGuard.PingHistory > 30 then
				table.remove(netGuard.PingHistory, 1)
			end
			if measurePing > netGuard.Config.PingThreshold then
				local now = os.clock()
				if now - netGuard.LastLagAt > 5 then
					netGuard.LastLagAt = now
					netGuard.LagSpikes = netGuard.LagSpikes + 1
					if Hub.AntiBan then
						Hub.AntiBan.AddScore(3, "lag-spike")
					end
				end
			end
		end
		function netGuard.PingVariance()
			if #netGuard.PingHistory < 5 then
				return 0
			end
			local count, count2, count3 = 0, 0, 0
			for index, item in ipairs(netGuard.PingHistory) do
				count = count + item
				count2 = count2 + item * item
				count3 = count3 + 1
			end
			local num = count / count3
			return math.sqrt(math.max(0, (count2 / count3) - (num * num)))
		end
		function netGuard.NoteFail()
			netGuard.ConsecutiveFails = netGuard.ConsecutiveFails + 1
			if netGuard.ConsecutiveFails >= netGuard.Config.MaxFails then
				local num = math.min(netGuard.Config.BackoffMax, netGuard.Config.BackoffMin * netGuard.ConsecutiveFails)
				netGuard.BackoffUntil = os.clock() + num
				netGuard.ConsecutiveFails = 0
				if Hub.say then
					Hub.say("][NetGuard] backoff " .. num .. "s")
				end
			end
		end
		function netGuard.NoteSuccess()
			netGuard.ConsecutiveFails = 0
		end
		function netGuard.IsBlocked()
			return os.clock() < netGuard.BackoffUntil
		end
		task.spawn(function()
			while isReplayToken() do
				task.wait(2)
				if netGuard.Config.Enabled then
					pcall(netGuard.CheckPing)
				end
			end
		end)
	end
