			{ Enabled = true, MaxSpeed = 500, MaxTeleport = 400, TeleportWindow = 10, MaxTeleportsInWindow = 5 }
		movementGuard.LastPos, movementGuard.LastT = nil, 0
		movementGuard.Teleports = {}
		function movementGuard.Check()
			if not movementGuard.Config.Enabled then
				return
			end
			local character = localPlayer.Character
			local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
			if not humanoidRootPart then
				movementGuard.LastPos = nil
				return
			end
			local now = os.clock()
			if movementGuard.LastPos then
				local lastT = now - movementGuard.LastT
				if lastT > 0.01 then
					local magnitude = (humanoidRootPart.Position - movementGuard.LastPos).Magnitude
					if magnitude > movementGuard.Config.MaxTeleport then
						movementGuard.Teleports[#movementGuard.Teleports + 1] = now
						while
							#movementGuard.Teleports > 0
							and now - movementGuard.Teleports[1] > movementGuard.Config.TeleportWindow
						do
							table.remove(movementGuard.Teleports, 1)
						end
						if #movementGuard.Teleports >= movementGuard.Config.MaxTeleportsInWindow then
							if Hub.AntiBan then
								Hub.AntiBan.AddScore(15, "teleport-spam")
							end
							if Hub.say then
								Hub.say("][MovementGuard] teleport spam -> pausing fly")
							end
							if Hub.Farm then
								Hub.Farm.PauseUntil = math.max(Hub.Farm.PauseUntil or 0, now + 3)
							end
							movementGuard.Teleports = {}
						end
					end
					local num = magnitude / lastT
					if num > movementGuard.Config.MaxSpeed and not (Hub.Farm and Hub.Farm.Refilling) then
						if Hub.AntiBan then
							Hub.AntiBan.AddScore(1, "speed")
						end
					end
				end
			end
			movementGuard.LastPos, movementGuard.LastT = humanoidRootPart.Position, now
		end
