	function Hub.ReportProblem(text, obj)
		obj = tostring(obj)
		Hub.out("][Smooth Hub] " .. text .. ": " .. obj)
		pcall(function()
			if type(makefolder) == "function" and type(isfolder) == "function" and not isfolder("SmoothHub") then
				makefolder("SmoothHub")
			end
			if type(writefile) == "function" then
				writefile("SmoothHub/LastError.txt", "build " .. tostring(Hub.BUILD) .. "\n" .. text .. "\n" .. obj)
			end
		end)
		pcall(function()
			if type(setclipboard) == "function" then
				setclipboard("][Smooth Hub " .. tostring(Hub.BUILD) .. "] " .. text .. "\n" .. obj)
			end
		end)
		pcall(function()
			game:GetService("StarterGui"):SetCore(
				"SendNotification",
				{ Title = "Smooth Hub - " .. text, Text = obj:sub(1, 180) .. "  (copied to clipboard)", Duration = 30 }
			)
		end)
	end
	task.delay(45, function()
