				if not (findFirstAncestorOfClass and findFirstAncestorOfClass.IgnoreGuiInset) then
					count = count + GuiService:GetGuiInset()
				end
				VirtualInputManager:SendMouseButtonEvent(count.X, count.Y, 0, true, game, 0)
