		local function handleNA()
			if flag2 then
				return false
			end
			if not placeId then
				tryTostring("N/A")
				return false
			end
			flag2 = true
			local element = list2[config.Slot] or "A"
			local flag = false
			local ok, result = pcall(function()
				local result = handleSlot(element)
				if not result then
					tryTostring(
						Hub.Slot.selected and ("Selected Slot " .. element) or ("Slot " .. element .. " UI not found")
					)
					return
				end
				Hub.Slot.seen = true
				tryTostring("Waiting for slot screen to load...")
				local key, count = Hub.Slot.Key(result), 0
				for i = 1, 20 do
					task.wait(0.2)
					if not isReplayToken() then
						return
					end
					if not (result.Parent and handleGuiObject(result)) then
						result = handleSlot(element)
						if not result then
							return
						end
						key, count = Hub.Slot.Key(result), 0
					else
						local key2 = Hub.Slot.Key(result)
						if key2 == key then
							count += 1
							if count >= 3 then
								break
							end
						else
							key, count = key2, 0
						end
					end
				end
				for i = 1, 3 do
					if not isReplayToken() then
						return
					end
					result = handleSlot(element)
					if not result then
						if not handleSlotA() then
							flag = true
						end
						break
					end
					tryTostring(("Selecting Slot %s... (try %d/3)"):format(element, i))
					if i == 2 then
						Hub.Slot.Click(result)
					else
						handleFunctionValue(result)
					end
					for i = 1, 12 do
						task.wait(0.25)
						if not handleSlotA() then
							flag = true
							break
						end
					end
					if flag then
						break
					end
				end
			end)
			if not ok then
				tryTostring("Select error: " .. tostring(result))
			end
			if flag then
				Hub.Slot.selected = true
				Hub.Slot.seen = true
				Hub.Slot.vis = false
				Hub.Slot.goneSince = os.clock()
				tryTostring("Selected Slot " .. element)
			elseif ok then
				tryTostring("Could not select Slot " .. element .. " - retrying")
			end
			flag2 = false
			return flag
		end
