			local function handleGuiButton3()
				local currentCamera = workspace.CurrentCamera
				local viewportSize = currentCamera and currentCamera.ViewportSize or Vector2.new(1920, 1080)
				local map, count = {}, 0
				for index, item in ipairs(playerGui:GetDescendants()) do
					count += 1
					if count % 800 == 0 then
						task.wait()
					end
					if item:IsA("GuiButton") and handleGuiObject(item) then
						local absoluteSize = item.AbsoluteSize
						if
							absoluteSize.X >= 40
							and absoluteSize.X <= 220
							and absoluteSize.Y >= 40
							and absoluteSize.Y <= 220
							and math.abs(absoluteSize.X / absoluteSize.Y - 1) <= 0.2
						then
							local num = item.AbsolutePosition + absoluteSize / 2
							if num.X < viewportSize.X * 0.3 then
								map[#map + 1] = { btn = item, y = num.Y }
							end
						end
					end
				end
				if #map < 4 then
					return nil
				end
				table.sort(map, function(data, data2)
					return data.y > data2.y
				end)
				return map[1].btn
			end
