		local function handleInterfaceInventoryMain2()
			local result = findByPath("Interface.Inventory.Main.Holder.Items")
			if not result then
				return nil
			end
			for index, item in ipairs(result:GetChildren()) do
				local match1, match2 = item.Name:match("^(%d+)%s*%-%s*(.+)$")
				if match1 and tonumber(match1) % 100 == 2 then
					local main = item:FindFirstChild("Main")
					local equipped = main and main:FindFirstChild("Equipped")
					if equipped and equipped:IsA("GuiObject") and equipped.Visible then
						local checkmark = equipped:FindFirstChild("Checkmark")
						local flag = true
						if checkmark and checkmark:IsA("ImageLabel") and checkmark.ImageTransparency >= 1 then
							flag = false
						end
						if flag then
							return match2
						end
					end
				end
			end
			return "None"
		end
