		local function normalizeText2(arg1)
			return (tostring(arg1):lower():gsub("][^%w]", ""))
		end
		function handleNumber(value)
			if type(value) == "number" then
				if value ~= math.floor(value) then
					return string.format("%.2f", value)
				end
				local text = tostring(math.floor(value))
				local flag = text:sub(1, 1) == "-"
				if flag then
					text = text:sub(2)
				end
				text = text:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
				return (flag and "-" or "") .. text
			end
			return tostring(value)
		end
		local function handleBoolean2(obj)
			if type(obj) == "boolean" then
				return obj
			end
			if type(obj) == "number" then
				return obj ~= 0
			end
			if type(obj) == "string" then
				local lowered = obj:lower()
				return lowered == "true" or lowered == "yes" or lowered == "1"
			end
			return false
		end
