				return typeName == "number" or typeName == "string" or typeName == "boolean"
			end
			local function handleValueBase(obj, value)
				pcall(function()
					for key, value in pairs(obj:GetAttributes()) do
						if handleNumber(value) then
							map[#map + 1] = { name = key, value = value, path = obj:GetFullName() .. " @" .. key }
						end
					end
					if obj:IsA("ValueBase") then
						local ok, result = pcall(function()
							return obj.Value
						end)
						if ok and handleNumber(result) then
							map[#map + 1] = { name = obj.Name, value = result, path = obj:GetFullName() }
						end
					end
				end)
				if value >= 6 then
					return
				end
				for index, item in ipairs(obj:GetChildren()) do
					if not options2[item.Name] then
						handleValueBase(item, value + 1)
					end
				end
			end
			for index, item in ipairs(list4) do
				if item and item.Parent then
					handleValueBase(item, 0)
				end
			end
			return map
		end
