				local result2 = (result.Text or ""):gsub("<[^>]->", "")
				result2 = result2:gsub("^%s+", ""):gsub("%s+$", "")
				if result2 ~= "" then
					return result2
				end
			end
			return nil
		end
		function handleTextLabel3(data)
			local instance = data and data.__instance
			if not instance then
				return nil
