		local function handleGuiObject(obj)
			local objRef = obj
			while objRef and objRef ~= playerGui do
				if objRef:IsA("GuiObject") and not objRef.Visible then
					return false
				end
				if objRef:IsA("ScreenGui") and not objRef.Enabled then
