			return tostring(arg1):lower():gsub("%s", "") == "m1"
		end
		local function handleGuiObject2(data)
			local dataRef, parent = data, data.Parent
			for i = 1, 4 do
				if not parent or parent == playerGui or not parent:IsA("GuiObject") then
					break
				end
				local x, y = parent.AbsoluteSize.X, parent.AbsoluteSize.Y
				if x >= 24 and x <= 220 and math.abs(x - y) <= x * 0.25 then
					dataRef = parent
				else
					break
				end
				parent = parent.Parent
			end
			return dataRef
		end
		local function handleM12(obj)
			if obj == "m1" or obj:match("]^m1[^%d]") or obj:match("][^%a]m1$") or obj:match("][^%a]m1[^%d]") then
				return 10
			end
			if obj:find("attack", 1, true) then
				return 6
			end
			if obj:find("slash", 1, true) or obj:find("swing", 1, true) then
				return 5
			end
			if obj:find("click", 1, true) then
				return 3
			end
			return 0
		end
		local function handleTitleScreen(obj)
			local lowered = obj:GetFullName():lower()
			if
				lowered:find("title_screen", 1, true)
				or lowered:find("smooth", 1, true)
				or lowered:find("cascade", 1, true)
			then
				return 0
			end
			local x = obj.AbsoluteSize.X
			if x < 24 or x > 260 then
				return 0
			end
			local result = handleM12(obj.Name:lower())
			if obj:IsA("TextButton") then
				result = math.max(result, handleM12(tostring(obj.Text):lower()))
			end
			local parent = obj.Parent
			for i = 1, 2 do
				if not parent or parent == playerGui then
					break
				end
				result = math.max(result, handleM12(parent.Name:lower()) * 0.6)
				parent = parent.Parent
			end
			return result
		end
