		local function getTouch(arg1, arg2, arg3)
			return {
				UserInputType = Enum.UserInputType.Touch,
				UserInputState = arg1,
				KeyCode = Enum.KeyCode.Unknown,
				Position = Vector3.new(arg2 or 0, arg3 or 0, 0),
				Delta = Vector3.new(0, 0, 0),
			}
		end
		local function handleFunctionValue(data, arg2, ...)
			if typeof(getconnections) ~= "function" then
				return 0
			end
			local packed = table.pack(...)
			local ok, result = pcall(function()
				return data[arg2]
			end)
			if not ok or not result then
				return 0
			end
			local ok2, result2 = pcall(getconnections, result)
			if not ok2 or type(result2) ~= "table" then
				return 0
			end
			local count = 0
			for index, item in ipairs(result2) do
				pcall(function()
					if item.Fire then
						item:Fire(table.unpack(packed, 1, packed.n))
					elseif item.Function then
						item.Function(table.unpack(packed, 1, packed.n))
					end
				end)
				count += 1
			end
			return count
		end
		local function handleMouseButton1Down(arg1, arg2, arg3)
