				end
				if not result1 then
					setRetryStatus("Retry click failed: " .. tostring(result2))
					return
				end
				task.wait(1)
				local result3 = handleTextLabel2(arg1, "^RETRY")
				local num2 = result3 and tonumber((trimText(result3):match("(%d+)%s*/%s*%d+")))
				local flag2 = (not result3) or (num2 and match1 and num2 > match1)
				if flag2 then
					count = num4
					if not flag then
						flag = true
						config.RetryDone += 1
						debounce()
						map2.RefreshRetry()
					end
					setRetryStatus("Retry clicked (" .. handleEndless(config.RetryDone) .. ")")
				else
					setRetryStatus("Click not registered - trying another method")
				end
			end
			while isReplayToken() do
				task.wait(timeout)
				if not (config.AutoRetry or config.AutoLeave or config.AutoLeaveWhenRetryComplete) then
					resetState()
					setRetryStatus("Off")
				elseif not isNotPlaceId() then
					resetState()
					setRetryStatus("Not available in the lobby / menu")
				else
					local result = handleTextLabel()
					if not result then
						value2 = value2 or os.clock()
						if os.clock() - value2 >= num3 then
							resetState()
						end
						if not value1 then
							if config.AutoRetry then
								setRetryStatus(
									"Waiting for the mission to finish (" .. handleEndless(config.RetryDone) .. ")"
								)
							else
								setRetryStatus("Waiting for the mission to finish")
							end
						end
					else
						value2 = nil
						value1 = value1 or os.clock()
						if os.clock() - value1 < num2 then
							setRetryStatus("Mission completed - preparing")
						elseif flag2 == "leave" or config.AutoLeave then
