				config["AutoSkillMode" .. i] = "Instant"
			end
		end
		local pageSection = tab5:PageSection({
			Title = "Auto Skill",
			Subtitle = "Presses skill keys 1-5. Instant = tap, Hold = hold.",
		})
		local form = pageSection:Form()
		local row = form:Row()
		row:Left():TitleStack({ Title = "Skill Status", Subtitle = "Current action..." })
		local label = row:Right():Label({ Text = "Off" })
		local valueRef = nil
		local function setText(value)
			if value == valueRef then
				return
			end
			valueRef = value
			pcall(function()
				label.Text = tostring(value)
			end)
		end
		local list3 = { "Slot 1", "Slot 2", "Slot 3", "Slot 4", "Slot 5" }
		local function handleTable(text, arg2, matches, setEntry)
			local row = form:Row()
			row:Left():TitleStack({ Title = text, Subtitle = arg2 })
			local function collectMatches()
				local map = {}
				for i = 1, 5 do
					if matches(i) then
						map[#map + 1] = i
					end
				end
				return map
			end
			local function handleTable(arg1)
				local arg1Ref = type(arg1) == "table" and arg1 or { arg1 }
				local map2 = {}
				for index, item in ipairs(map.ValidIndexes(arg1Ref, 5)) do
					map2[item] = true
				end
				for i = 1, 5 do
					setEntry(i, map2[i] and true or false)
				end
				debounce()
			end
			local ok, result = pcall(function()
				return row:Right():PopUpButton({
					Options = list3,
					Maximum = 5,
					Value = collectMatches(),
					ValueChanged = function(_, arg2)
						handleTable(arg2)
					end,
				})
			end)
			if ok and result then
				pcall(handlePullDownIndicator, result)
				options.Add(function()
					pcall(function()
						result.Value = collectMatches()
					end)
				end)
			else
				for i = 1, 5 do
					local row = form:Row()
					row:Left():TitleStack({ Title = text .. " [ " .. i .. "] ]", Subtitle = arg2 })
					local toggle = row:Right():Toggle({
						Value = matches(i) and true or false,
						ValueChanged = function(_, arg2)
							setEntry(i, arg2 and true or false)
							debounce()
						end,
					})
					options.Add(function()
						pcall(function()
							toggle.Value = matches(i) and true or false
						end)
					end)
				end
			end
		end
		handleTable("Enabled Slots", "Tick the skill slots (keys 1-5) to auto press.", function(text)
			return config["AutoSkill" .. text]
		end, function(text, arg2)
			config["AutoSkill" .. text] = arg2
		end)
		handleTable("Hold Slots", "Tick slots to hold the key. Unticked slots are tapped (Instant).", function(text)
			return config["AutoSkillMode" .. text] == "Hold"
		end, function(text, arg2)
			config["AutoSkillMode" .. text] = arg2 and "Hold" or "Instant"
		end)
		local function buildTitleRow(formatTitle, arg2, arg3)
			local element = config2[arg3]
			local row = form:Row()
			local titleStack = row:Left():TitleStack({ Title = formatTitle(config[arg3]), Subtitle = arg2 })
			options.Link(
				row:Right():Slider({
					Minimum = element[1],
					Maximum = element[2],
					Value = config[arg3],
					ValueChanged = function(_, value)
						local num = math.clamp(math.floor(value + 0.5), element[1], element[2])
						config[arg3] = num
						pcall(function()
							titleStack.Title = formatTitle(num)
						end)
						debounce()
					end,
				}),
				config,
				arg3,
				function(_, arg2)
					pcall(function()
						titleStack.Title = formatTitle(arg2)
					end)
				end
			)
		end
		buildTitleRow(function(text)
			return "Hold Time ( " .. text .. "s )"
		end, "How long the key is held in Hold mode.", "AutoSkillHoldTime")
		buildTitleRow(function(text)
			return "Press Delay ( " .. text .. "s )"
		end, "Wait before pressing the same slot again.", "AutoSkillDelay")
		local function handleAutoSkill()
			for i = 1, 5 do
				if config["AutoSkill" .. i] then
					return true
				end
			end
			return false
		end
		local function handleNotAvailableInTheLob()
			if not map2.CanUseHere() then
				return false, "Not available in the lobby / menu"
			end
			if UserInputService:GetFocusedTextBox() then
				return false, "Typing in chat - paused"
			end
			local character = localPlayer.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			if not humanoid or humanoid.Health <= 0 then
				return false, "Waiting for your character"
			end
			if map2.CompleteScreenShown and map2.CompleteScreenShown() then
				return false, "Mission completed - paused"
			end
			return true
		end
		local function handleGuiButton(arg1)
			local itemRef = nil
			for index, item in ipairs(playerGui:GetDescendants()) do
				if item:IsA("GuiButton") and item.Visible and item.AbsoluteSize.X > 0 and item.AbsoluteSize.Y > 0 then
					local lowered = item.Name:lower()
					local found = lowered:find("skill") or lowered:find("ability") or lowered:find("slot")
					if found and lowered:find(tostring(arg1)) then
						itemRef = item
						break
					end
				end
			end
			return itemRef
		end
		local function simulateTap(data, arg2)
			local num = data.AbsolutePosition + data.AbsoluteSize / 2
			local random = math.random(100000, 999999)
			pcall(function()
				VirtualInputManager:SendTouchEvent(random, 0, num.X, num.Y)
			end)
			if arg2 then
				task.wait(arg2)
			else
				task.wait(0.06)
			end
			pcall(function()
				VirtualInputManager:SendTouchEvent(random, 2, num.X, num.Y)
			end)
		end
		local function handleAutoSkillMode(text)
			local element = list2[text]
			local flag = UserInputService.TouchEnabled and not UserInputService.MouseEnabled
			if flag then
				local result = handleGuiButton(text)
				if result then
					if config["AutoSkillMode" .. text] == "Hold" then
						simulateTap(result, config.AutoSkillHoldTime)
					else
						simulateTap(result, nil)
					end
				end
			else
				if config["AutoSkillMode" .. text] == "Hold" then
					pcall(function()
						VirtualInputManager:SendKeyEvent(true, element, false, game)
					end)
					local now = os.clock()
					while
						os.clock() - now < config.AutoSkillHoldTime
						and isReplayToken()
						and config["AutoSkill" .. text]
						and handleNotAvailableInTheLob()
					do
						task.wait(0.1)
					end
					pcall(function()
						VirtualInputManager:SendKeyEvent(false, element, false, game)
					end)
				else
					pcall(function()
						VirtualInputManager:SendKeyEvent(true, element, false, game)
						task.wait(0.06)
						VirtualInputManager:SendKeyEvent(false, element, false, game)
					end)
				end
			end
		end
		local list4 = { 0, 0, 0, 0, 0 }
		task.spawn(function()
			while isReplayToken() do
				task.wait(0.25)
				if not handleAutoSkill() then
					setText("Off")
				else
					local result1, result2 = handleNotAvailableInTheLob()
					if not result1 then
						setText(result2)
					else
						setText("Waiting for next press...")
						for i = 1, 5 do
							if config["AutoSkill" .. i] and os.clock() >= list4[i] then
								setText("Using slot " .. i .. " (" .. config["AutoSkillMode" .. i] .. ")")
								handleAutoSkillMode(i)
								list4[i] = os.clock() + config.AutoSkillDelay
								task.wait(0.15)
