									break
								end
							end
						end
					end
				end
			end
		end)
	end)
	local section2 = result.Components.Section(window, { Title = "Lobby", Disclosure = false })
	task.wait()
	local tab6 = section2:Tab({ Title = "Lobby", Icon = handleBoltFill("cubeFill", "shippingboxFill", "cube") })
	do
