		buildTitleRow("Auto Claim Side Quests", "Automatically claim the side quests.", "AutoClaimSide")
		buildTitleRow("Auto Claim Achievements", "Automatically claim achievements.", "AutoClaimAchievements")
		buildTitleRow("Auto Claim Weekly Quests", "Automatically claim the weekly quests.", "AutoClaimWeekly")
		buildTitleRow("Auto Claim Daily Quests", "Automatically claim the daily quests.", "AutoClaimDaily")
		buildTitleRow(
			"Auto Open Pages",
			"Opens Achievements when the red ! shows, claims, then closes.",
			"AutoOpenPages"
		)
		buildTitleRow(
			"Auto Close Daily Rewards",
			"Closes the Daily Rewards popup in the lobby.",
			"AutoCloseDailyReward"
		)
		do
			local map = { tries = 0, blockedUntil = 0, logged = false }
			function map.Title()
				for index, item in ipairs(playerGui:GetDescendants()) do
					if
						handleTextLabel(item)
						and normalizeText(item):find("^DAILY REWARDS")
						and handleGuiObject(item)
					then
						return item
					end
				end
				return nil
			end
			function map.LooksLikeClose(data)
				local lowered = data.Name:lower()
				if
					lowered:find("close", 1, true)
					or lowered:find("exit", 1, true)
					or lowered:find("cancel", 1, true)
					or lowered == "x"
				then
					return true
				end
				if handleTextLabel(data) then
					local result = normalizeText(data)
					if result == "X" or result == "\195\151" then
						return true
					end
				end
				return false
			end
			function map.FindClose(data)
				local parent = data.Parent
				for i = 1, 8 do
					if not parent or parent == playerGui then
						break
					end
					for index, item in ipairs(parent:GetDescendants()) do
						if item:IsA("GuiButton") and handleGuiObject(item) and map.LooksLikeClose(item) then
							return item
						end
						if
							item:IsA("GuiObject")
							and not item:IsA("GuiButton")
							and item.Name:lower():find("close", 1, true)
							and handleGuiObject(item)
						then
							local guiButton = item:FindFirstChildWhichIsA("GuiButton", true)
							if guiButton and handleGuiObject(guiButton) then
								return guiButton
							end
						end
					end
					parent = parent.Parent
				end
				local dataRef = data
				while dataRef.Parent and dataRef.Parent ~= playerGui and not dataRef.Parent:IsA("ScreenGui") do
					dataRef = dataRef.Parent
				end
				local currentCamera = workspace.CurrentCamera
				local viewportSize = currentCamera and currentCamera.ViewportSize or Vector2.new(1920, 1080)
				local x1, negNum = nil, -1
				for index, item in ipairs(dataRef:GetDescendants()) do
					if item:IsA("GuiButton") and handleGuiObject(item) then
						local absolutePosition, absoluteSize = item.AbsolutePosition, item.AbsoluteSize
						if
							absoluteSize.X <= 130
							and absoluteSize.Y <= 130
							and absolutePosition.Y < viewportSize.Y * 0.25
							and absolutePosition.X > viewportSize.X * 0.5
							and absolutePosition.X > negNum
						then
							x1, negNum = item, absolutePosition.X
						end
					end
				end
				return x1
			end
			function map.Press(obj)
