					VirtualInputManager:SendMouseButtonEvent(num.X, num.Y, 0, false, game, 0)
				end)
				task.wait(0.6)
				pcall(function()
					if GuiService.SelectedObject == obj then
						GuiService.SelectedObject = nil
					end
				end)
				return map.Title() == nil
			end
			task.spawn(function()
				while isReplayToken() do
					task.wait(1.2)
					if config.AutoCloseDailyReward and placeId and os.clock() >= map.blockedUntil and not flag2 then
						local ok, result = pcall(function()
							local title = map.Title()
							if not title then
								map.tries = 0
								map.logged = false
								return
							end
							local findClose = map.FindClose(title)
							if not findClose then
								if not map.logged then
									map.logged = true
									Hub.say(
										"Daily Rewards is open but its close (X) button was not found: "
											.. title:GetFullName()
									)
								end
								return
							end
							Hub.say("Closing Daily Rewards via " .. findClose:GetFullName())
							tryTostring("Closing Daily Rewards popup...")
							if map.Press(findClose) then
								map.tries = 0
								tryTostring("Daily Rewards popup closed")
							else
								map.tries += 1
								if map.tries >= 3 then
