			local function trimText(obj)
				return (obj:match("^%s*(.-)%s*$"))
			end
			local function handleString(obj)
				if type(obj) ~= "string" or obj == "" then
					return nil
				end
				if obj:find("<", 1, true) then
					return nil
				end
				local element = options[en]
				if not element then
					return nil
				end
				local element2 = element[obj] or element[trimText(obj)]
				if element2 then
					return element2
				end
				for index, item in ipairs(options2[en] or {}) do
					if obj:sub(1, #item[1]) == item[1] then
						return item[2] .. obj:sub(#item[1] + 1)
					end
				end
				return nil
			end
			function Hub.T(arg1)
				if type(arg1) ~= "string" or en == "EN" then
					return arg1
				end
				return handleString(arg1) or arg1
