			local obj = setmetatable({}, { __mode = "k" })
			local flag = false
			local resultRef, connection = nil, nil
			local function handleTextLabel(obj)
				return obj:IsA("TextLabel") or obj:IsA("TextButton")
			end
			local function handleEn(data)
				local element = obj[data]
				if not element then
					return
				end
				local text = data.Text
				if text ~= element.shown then
					element.orig = text
				end
				local orig = element.orig
				if en ~= "EN" then
					orig = handleString(element.orig) or element.orig
				end
				element.shown = orig
				if text ~= orig then
					flag = true
					pcall(function()
						data.Text = orig
					end)
					flag = false
				end
			end
			local function handleText(obj2)
				if obj[obj2] or not handleTextLabel(obj2) then
					return
				end
				local map = { orig = obj2.Text, shown = obj2.Text }
				obj[obj2] = map
				map.conn = obj2:GetPropertyChangedSignal("Text"):Connect(function()
					if flag then
						return
					end
					handleEn(obj2)
				end)
				if en ~= "EN" then
					handleEn(obj2)
				end
			end
			local function processBatched()
				local count = 0
				for key in pairs(obj) do
					if key.Parent then
						handleEn(key)
					end
					count += 1
					if count % 400 == 0 then
						task.wait()
					end
				end
			end
			local function handleScreenGui(data)
				local findFirstAncestorOfClass
				pcall(function()
					if data and data.__instance then
						findFirstAncestorOfClass = data.__instance:FindFirstAncestorOfClass("ScreenGui")
					end
				end)
				if not findFirstAncestorOfClass then
					pcall(function()
						findFirstAncestorOfClass = window.__instance
							and window.__instance:FindFirstAncestorOfClass("ScreenGui")
					end)
				end
				if not findFirstAncestorOfClass then
					local data = {}
					if type(gethui) == "function" then
						pcall(function()
							table.insert(data, gethui())
						end)
					end
					pcall(function()
						table.insert(data, game:GetService("CoreGui"))
					end)
					for index, item in ipairs(data) do
						for index, item in ipairs(item:GetChildren()) do
							if
								item:IsA("ScreenGui")
								and (item.Name:find("Smooth Hub", 1, true) or item.Name:find("Cascade", 1, true))
								and item.Name ~= "SmoothHubToggle"
							then
								findFirstAncestorOfClass = item
								break
							end
						end
						if findFirstAncestorOfClass then
							break
						end
					end
				end
				return findFirstAncestorOfClass
			end
			local function handleSmoothHubLanguage(arg1)
				local result = handleScreenGui(arg1)
