			handlePullDownIndicator(pullDownButton3)
			refreshDropdown = function(arg1)
				local list = { "---" }
				for index, item in ipairs(defaults.Names()) do
					list[#list + 1] = item
				end
				list3 = list
				local found = (arg1 and table.find(list, arg1)) or 1
