				tryTostring("Autoload reset")
			end)
			label3 = buildTitleRow("Current autoload config", "Loaded when the script starts."):Label({ Text = "none" })
			Hub.Guard("config-share", function()
				local shcfg1 = "SHCFG1:"
				local path = "SmoothHub/Share"
				local num = 300000
				local path2 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
				local map = {}
				for i = 1, #path2 do
					map[path2:byte(i)] = i - 1
				end
				local function joinItems(obj)
					local map = {}
					for i = 1, #obj, 3 do
						local byte1, byte2, byte3 = obj:byte(i, i + 2)
						local result = byte1 * 65536 + (byte2 or 0) * 256 + (byte3 or 0)
						local num = bit32.rshift(result, 18) % 64
						local num2 = bit32.rshift(result, 12) % 64
						local num3 = bit32.rshift(result, 6) % 64
						local num4 = result % 64
						map[#map + 1] = path2:sub(num + 1, num + 1)
							.. path2:sub(num2 + 1, num2 + 1)
							.. (byte2 and path2:sub(num3 + 1, num3 + 1) or "=")
							.. (byte3 and path2:sub(num4 + 1, num4 + 1) or "=")
					end
					return table.concat(map)
				end
				local function joinItems2(obj)
					obj = (obj:gsub("][^%w%+/=]", ""))
					local map2 = {}
					for i = 1, #obj, 4 do
						local byte1, byte2, byte3, byte4 = obj:byte(i, i + 3)
						local element, element2 = map[byte1], map[byte2 or 0]
						if not element or not element2 then
							return nil
						end
						local element3 = (byte3 and byte3 ~= 61) and map[byte3] or nil
						local element4 = (byte4 and byte4 ~= 61) and map[byte4] or nil
						local result = element * 262144 + element2 * 4096 + (element3 or 0) * 64 + (element4 or 0)
						map2[#map2 + 1] = string.char(bit32.rshift(result, 16) % 256)
						if element3 then
							map2[#map2 + 1] = string.char(bit32.rshift(result, 8) % 256)
						end
						if element4 then
							map2[#map2 + 1] = string.char(result % 256)
						end
					end
					return table.concat(map2)
				end
				local function handleTable(data, data2)
					if type(data) ~= type(data2) then
						return false
					end
					if type(data) == "table" then
						if #data ~= #data2 then
							return false
						end
						for i = 1, #data do
							if data[i] ~= data2[i] then
								return false
							end
						end
						return true
					end
					return data == data2
				end
				local function collectItems(arg1, data)
					local map = {}
					data = data or {}
					for key, value in pairs(arg1 or {}) do
						if not handleTable(value, data[key]) then
							map[key] = value
						end
					end
					return map
				end
				local function handleTable2(arg1)
					if type(arg1) ~= "table" then
						return arg1
					end
					local map = {}
					for index, item in ipairs(arg1) do
						map[index] = item
					end
					return map
				end
				local function getGet()
					return defaults.Get(defaults.DEFAULT_NAME) or { Cfg = {}, Hub = {}, UI = {} }
				end
				local function handleTable3(arg1)
					local map = {}
					if type(arg1) ~= "table" then
						return map
					end
					for key, value in pairs(arg1) do
						if type(key) == "string" and #key <= 60 then
							local typeName = type(value)
							if
								typeName == "boolean"
								or (typeName == "number" and value == value and value > -1e12 and value < 1e12)
								or (typeName == "string" and #value <= 500)
							then
								map[key] = value
							elseif typeName == "table" and #value <= 50 then
								local map2 = {}
								for index, item in ipairs(value) do
									if type(item) == "string" and #item <= 100 then
										map2[#map2 + 1] = item
									end
								end
								map[key] = map2
							end
						end
					end
					return map
				end
				local function handleShared(arg1)
					local response = arg1 and defaults.Get(arg1)
					if not response then
						response = defaults.Snapshot(config2)
						arg1 = defaults.Active() or "Shared"
					end
					local result = getGet()
					local data = {
						n = arg1,
						c = collectItems(response.Cfg, result.Cfg),
						h = collectItems(response.Hub, result.Hub),
						u = collectItems(response.UI, result.UI),
					}
					local ok, result2 = pcall(function()
						return HttpService:JSONEncode(data)
					end)
					if not ok then
						return nil
					end
					return shcfg1 .. joinItems(result2), arg1
				end
				local function handlePasteAShareCodeLink(obj)
					obj = tostring(obj or ""):match("^%s*(.-)%s*$")
					if obj == "" then
						return nil, "Paste a share code, link or file name first"
					end
					if obj:match("^https?://") then
						local ok, result = pcall(function()
							return game:HttpGet(obj)
						end)
						if not ok or type(result) ~= "string" or result == "" then
							return nil, "Download failed (check the link)"
						end
						return result
					end
					if obj:find(shcfg1, 1, true) then
						return obj
					end
					if obj:find("{", 1, true) and obj:find("=", 1, true) then
						return obj
					end
					if type(isfile) == "function" and type(readfile) == "function" then
						for index, item in ipairs({ path .. "/" .. obj, path .. "/" .. obj .. ".txt", obj }) do
							local ok, result = pcall(isfile, item)
							if ok and result then
								local ok, result = pcall(readfile, item)
								if ok and type(result) == "string" then
									return result
								end
							end
						end
					end
					return nil, "Not a valid share code, link or file"
				end
				local function handleNotASmoothHubShareC(obj)
					obj = (tostring(obj):gsub("%s", ""))
					local found = obj:find(shcfg1, 1, true)
					if not found then
						return nil, "Not a Smooth Hub share code"
					end
					obj = obj:sub(found + #shcfg1)
					if #obj > num then
						return nil, "Code is too large"
					end
					local result = joinItems2(obj)
					if not result or result == "" then
						return nil, "Code is damaged"
					end
					local ok, result2 = pcall(function()
						return HttpService:JSONDecode(result)
					end)
					if not ok or type(result2) ~= "table" then
						return nil, "Code is damaged"
					end
					return result2
				end
				local function mergeTyped(arg1, data, data2)
					for key, value in pairs(handleTable3(arg1)) do
						local element = data and data[key]
						if element ~= nil and type(element) == type(value) then
							data2[key] = handleTable2(value)
						end
					end
				end
				local function handleString(arg1)
					local result1, result2 = handlePasteAShareCodeLink(arg1)
					if not result1 then
						return nil, result2
					end
					local result = getGet()
					local options = { Cfg = {}, Hub = {}, UI = {} }
					for key, value in pairs(result.Cfg or {}) do
						options.Cfg[key] = handleTable2(value)
					end
					for key, value in pairs(result.Hub or {}) do
						options.Hub[key] = value
					end
					for key, value in pairs(result.UI or {}) do
						options.UI[key] = value
					end
					local result3, summary
					if result1:find(shcfg1, 1, true) then
						local result12, result2 = handleNotASmoothHubShareC(result1)
						if not result12 then
							return nil, result2
						end
						mergeTyped(result12.c, result.Cfg, options.Cfg)
						mergeTyped(result12.h, result.Hub, options.Hub)
						mergeTyped(result12.u, result.UI, options.UI)
						result3 = sanitizeFilename(type(result12.n) == "string" and result12.n or "") or "Shared"
					else
						local parse1, parse2 = Hub.Legacy.Parse(result1)
						if not parse1 then
							return nil, parse2
						end
						local translate = Hub.Legacy.Translate(parse1)
						if #translate.applied == 0 then
							return nil, "No supported settings found in that config"
						end
						mergeTyped(translate.cfg, result.Cfg, options.Cfg)
						mergeTyped(translate.hub, result.Hub, options.Hub)
						result3 = "Imported Config"
						summary = Hub.Legacy.Summary(translate)
						if #translate.skipped > 0 then
							Hub.say("Not supported (skipped): " .. table.concat(translate.skipped, ", "))
						end
					end
					local result3Ref, count = result3, 1
					while defaults.Exists(result3Ref) do
						count = count + 1
						result3Ref = result3 .. " (" .. count .. ")"
					end
					local put = defaults.Put(result3Ref, options)
					return result3Ref, nil, put, summary
				end
				local isFunctionValue2 = type(setclipboard) == "function"
					or type(toclipboard) == "function"
					or (syn and syn.write_clipboard ~= nil)
					or (Clipboard and Clipboard.set ~= nil)
				local form = tab17
					:PageSection({
						Title = "Share config",
						Subtitle = "Share your config with a short code, or import one.",
					})
					:Form()
				local function buildTitleRow(arg1, arg2)
					local row = form:Row()
					row:Left():TitleStack({ Title = arg1, Subtitle = arg2 })
					return row:Right()
				end
				local label =
					buildTitleRow("Share status", "Result of the last share / import."):Label({ Text = "Ready" })
				local function setText(arg1)
					tryTostring(arg1)
					pcall(function()
						label.Text = tostring(arg1)
					end)
				end
				local function createButton(arg1, arg2, arg3, arg4)
					local button = buildTitleRow(arg1, arg2):Button({ Label = arg3, Callback = function() end })
					handleTextButton(button, arg4)
					return button
				end
				createButton(
					"Copy share code",
					"Copies the selected config (or your current switches if none is selected). Paste it in Discord.",
					"Copy",
					function()
						local result1, result2 = handleShared(elementRef)
						if not result1 then
							setText("Could not build the code")
							return
						end
						local flag = false
						if isFunctionValue and type(writefile) == "function" then
							pcall(function()
								if type(makefolder) == "function" and type(isfolder) == "function" then
									if not isfolder("SmoothHub") then
										makefolder("SmoothHub")
									end
									if not isfolder(path) then
										makefolder(path)
									end
								end
								local result = tostring(result2):gsub("][^%w_%- ]", "_")
								writefile(path .. "/" .. result .. ".txt", result1)
								flag = true
							end)
						end
						if isFunctionValue2 then
							tryToclipboard(result1)
							setText(
								'Copied "'
									.. tostring(result2)
									.. '" ('
									.. #result1
									.. " chars)"
									.. (
										#result1 > 1900
											and " - too long for a normal Discord message, send as a .txt file"
										or ""
									)
							)
						elseif flag then
							setText("No clipboard - saved to workspace/" .. path .. "/")
						else
							setText("No clipboard and can't save files")
						end
					end
				)
				local text = ""
				buildTitleRow(
					"Import code / link / file",
					"Paste a share code, a getgenv().Configs text, a link to a .txt, or a file name from workspace/"
						.. path
						.. "/"
				):TextField({
					Placeholder = "SHCFG1:...  |  getgenv().Configs = {...}  |  https://...  |  file.txt",
					Value = "",
					TextChanged = function(_, arg2)
						text = tostring(arg2 or "")
					end,
					ValueChanged = function(_, arg2)
						text = tostring(arg2 or "")
					end,
				})
				createButton(
					"Import config",
					"Adds it to your Config list. Pick it in Config list and press Load to use it.",
					"Import",
					function()
						setText("Importing...")
						local ok, result, result2, result3, result4 = pcall(handleString, text)
						if not ok then
							setText("Import failed")
							return
						end
						if not result then
							setText("Failed: " .. tostring(result2))
							return
						end
						refreshDropdown(result)
						handleNone()
						setText(
							"Imported: "
								.. result
								.. (result4 and (" (" .. result4 .. ")") or "")
								.. (result3 == false and " (not saved to file)" or "")
								.. " - press Load"
						)
					end
				)
			end)
			handleNone2()
			handleNone()
			refreshDropdown(defaults.Active())
			task.spawn(function()
				while isReplayToken() do
					if not defaults.AutoSync() then
						handleNone()
					end
					task.wait(1)
				end
			end)
			function options.ResetAll()
				defaults.SyncActive(config2)
				defaults.SetActive(nil)
				handleNone()
				for key, value in pairs(options.Defaults.Cfg) do
					if type(value) == "table" then
						local map = {}
						for index, item in ipairs(value) do
							map[index] = item
						end
						config[key] = map
					else
						config[key] = value
					end
				end
				for key, value in pairs(options.Defaults.Hub) do
					config2[key] = value
				end
				debounce()
				options.Refresh()
				pcall(map2.Fps.Apply)
				handleTable(defaults.DEFAULT_LOOK)
			end
			local num = 0
			setState(
				"Reset to defaults",
				"Resets all switches and the window look. Saved configs stay.",
				"Reset",
				function()
					if os.clock() - num > 5 then
						num = os.clock()
						tryTostring("Press Reset again within 5s to confirm")
						return
					end
					num = 0
					options.ResetAll()
					tryTostring("Everything is back to the default values")
				end,
				"Destructive"
			)
			map.OnSaved = function()
				defaults.SyncActive(config2)
			end
		end
		map.StartAutoSave("AOTR", function()
