			"AutoFarmSmart",
			"AutoClearWave",
			"AutoQuestThunder",
			"AutoQuestThunderR1",
			"AutoQuestThunderR2",
			"AutoQuestThunderR3",
			"AutoCannon",
			"AutoRetry",
			"AutoReady",
			"AutoVoteSkip",
			"AutoCreateMission",
			"AutoStartMission",
			"AdvAutoStartMission",
			"AutoCreateRaid",
			"AutoStartRaid",
			"AutoCreateWave",
			"AutoStartWave",
			"AutoRefillsBlade",
			"AutoRefillsThunder",
			"AutoRefillWave",
			"RefillEnabled",
			"AutoFailSafe",
		}
		local function applySetting(arg1, arg2)
			config[arg1] = arg2
			local element = map2.Toggles and map2.Toggles[arg1]
			if element then
				pcall(function()
					element.Value = arg2
				end)
			end
		end
		local function isNotPlaceId()
			return not placeId and game.PlaceId ~= PLACE_ID
		end
		local function handleAssets()
			local ok, result = pcall(function()
				return ReplicatedStorage:WaitForChild("Assets", 5).Remotes:WaitForChild("POST", 5)
			end)
			if ok and result then
				pcall(function()
					Hub.Net.Fire(result, "Functions", "Teleport")
				end)
			end
		end
		local function pauseForWarning()
			pause.Saved = {}
			for index, item in ipairs(list) do
				if config[item] == true then
					pause.Saved[#pause.Saved + 1] = item
				end
			end
			pause.Active, pause.Since = true, os.time()
			pause.Save()
			for index, item in ipairs(pause.Saved) do
				applySetting(item, false)
			end
			debounce()
			pcall(options.Refresh)
			Hub.say(
				("][Warning Pause] %d/%d warnings - farm stopped, waiting in the lobby"):format(warn.Count(), warn.MAX)
			)
		end
		local function handleWarningPauseResumed(arg1)
			for index, item in ipairs(pause.Saved) do
				applySetting(item, true)
			end
			pause.Saved, pause.Active = {}, false
			pause.Save()
			debounce()
			pcall(options.Refresh)
			Hub.say("][Warning Pause] resumed (" .. tostring(arg1) .. ")")
		end
		function pause.StatusText()
			if not pause.Enabled and not pause.Active then
				return "Off"
			end
			if pause.Active then
				local nextExpiry = warn.NextExpiry()
				local formatted = nextExpiry
						and ("%d:%02d"):format(math.floor(nextExpiry / 60), math.floor(nextExpiry % 60))
					or "-"
				return ("Paused - waiting in lobby | next warning expires in %s"):format(formatted)
			end
			return ("Watching | warnings %d/%d, pause at %d"):format(warn.Count(), warn.MAX, pause.Limit)
		end
		task.spawn(function()
			local num = 0
			task.wait(5)
			while isReplayToken() do
				task.wait(2)
				pcall(function()
					if pause.Active then
						if not pause.Enabled then
							handleWarningPauseResumed("pause switched off")
							return
						end
						local flag = false
						for index, item in ipairs(list) do
							if config[item] == true then
								applySetting(item, false)
								flag = true
							end
						end
						if flag then
							debounce()
							pcall(options.Refresh)
						end
						if warn.Count() < pause.Limit then
							handleWarningPauseResumed("a warning expired")
							return
						end
						if isNotPlaceId() and os.clock() - num > 20 then
							num = os.clock()
							handleAssets()
						end
					elseif pause.Enabled and warn.Count() >= pause.Limit then
						pauseForWarning()
					end
				end)
			end
		end)
	end)
	Hub.prof("everything built")
	Hub.say("Loaded successfully (" .. (placeId and "Lobby" or "In-game") .. ").")
	Hub.Built = true
end, function(arg1)
	return tostring(arg1) .. "\n" .. debug.traceback()
end, ...)
if not ok then
	warn("][Smooth Hub] script crashed: " .. tostring(result))
	pcall(function()
		if type(makefolder) == "function" and type(isfolder) == "function" and not isfolder("SmoothHub") then
			makefolder("SmoothHub")
		end
		if type(writefile) == "function" then
			writefile("SmoothHub/LastError.txt", [[AE25 crash
]] .. tostring(result))
		end
	end)
	pcall(function()
		if type(setclipboard) == "function" then
			setclipboard([=[][Smooth Hub AE25 crash]
]=] .. tostring(result))
		end
	end)
	pcall(function()
		game:GetService("StarterGui"):SetCore("SendNotification", {
			Title = "Smooth Hub - script crashed",
			Text = tostring(result):sub(1, 180) .. "  (copied to clipboard)",
			Duration = 30,
		})
	end)
end
